"""Write assets/js/photos.js from the downloaded image folders."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
ALIENS = ROOT / "assets" / "img" / "aliens"
CHARS = ROOT / "assets" / "img" / "characters"

aliens = sorted(p.stem for p in ALIENS.glob("*.webp"))
chars = sorted(p.stem for p in CHARS.glob("*.webp")) if CHARS.exists() else []

lines = [
    "/* Generated by tools/build_photo_manifest.py — do not edit by hand. */",
    "window.B10_PHOTOS = {",
    "  aliens: " + json.dumps({s: 1 for s in aliens}, separators=(",", ":")) + ",",
    "  characters: " + json.dumps({s: 1 for s in chars}, separators=(",", ":")) + ",",
    "  counts: " + json.dumps({"aliens": len(aliens), "characters": len(chars)}) + "",
    "};",
    "",
]
out = ROOT / "assets" / "js" / "photos.js"
out.write_text("\n".join(lines), encoding="utf-8")
print("wrote", out, len(aliens), "aliens,", len(chars), "characters")
